import {DatabaseSync} from 'node:sqlite';
import {readFileSync,readdirSync} from 'node:fs';
import {WeatherService} from '../../lib/weather-service.mjs';
import {WatchService} from '../../lib/watch-service.mjs';
export function database(){const sqlite=new DatabaseSync(':memory:');for(const name of readdirSync(new URL('../../drizzle/',import.meta.url)).filter(f=>f.endsWith('.sql')).sort())sqlite.exec(readFileSync(new URL('../../drizzle/'+name,import.meta.url),'utf8'));return {prepare(sql){const stmt=sqlite.prepare(sql);let values=[];return {bind(...v){values=v;return this;},async first(){return stmt.get(...values)||null;},async all(){return {results:stmt.all(...values)};},async run(){return stmt.run(...values);},runSync(){return stmt.run(...values);}};},async batch(statements){sqlite.exec('BEGIN');try{for(const s of statements)s.runSync();sqlite.exec('COMMIT');}catch(e){sqlite.exec('ROLLBACK');throw e;}},close(){sqlite.close();}};}

export function setup(){const db=database();let now=Date.parse('2026-10-28T20:00:00Z')/1000,wind=10;const weather=new WeatherService(db,{clock:()=>now,fetcher:async url=>({ok:true,json:async()=>url.includes('/points/')?{properties:{forecastHourly:'https://api.weather.gov/gridpoints/LWX/1,1/forecast/hourly',forecastZone:'https://api.weather.gov/zones/forecast/VAZ001'}}:{properties:{updateTime:new Date(now*1000).toISOString(),periods:Array.from({length:25},(_,i)=>({startTime:new Date((now+i*3600)*1000).toISOString(),endTime:new Date((now+(i+1)*3600)*1000).toISOString(),temperature:70,temperatureUnit:'F',windSpeed:wind+' mph',probabilityOfPrecipitation:{value:20,unitCode:'wmoUnit:percent'}}))}}})});const service=new WatchService(weather),input={id:crypto.randomUUID(),label:'Home <&>',lat:39,lon:-77,settings:{alerts:true,windMph:20}};return {db,weather,service,input,alerts:()=>({features:[],collected_at:new Date(now*1000).toISOString(),revision:'a'}),advance:()=>now+=3601,wind:v=>wind=v};}

export async function pushKeys(){const pair=await crypto.subtle.generateKey({name:'ECDSA',namedCurve:'P-256'},true,['sign','verify']);return crypto.subtle.exportKey('jwk',pair.privateKey);}
